mapper.sql:
SELECT index_version FROM semantic_lexical_index_state
WHERE

  status = 'RECOVERY_READY' AND content_fingerprint = #{revision} AND index_version = #{indexVersion}
  status = 'READY' AND content_fingerprint = #{revision}

ORDER BY completed_at DESC, index_version DESC LIMIT 1

SELECT stats.term AS term, stats.document_frequency AS documentFrequency FROM semantic_lexical_term_stats stats WHERE stats.index_version = (
) AND stats.term IN
#{term}
ORDER BY stats.document_frequency, stats.term

SELECT t.target AS target, t.chunk_id AS chunkId, c.document_id AS documentId, t.term AS term, SUM(t.term_frequency * t.field_weight) AS weightedTermFrequency, stats.document_frequency AS documentFrequency, state.active_chunk_count AS activeChunkCount, state.average_weighted_length AS averageWeightedLength, c.weighted_length AS weightedLength FROM semantic_lexical_terms t FORCE INDEX (idx_semantic_lexical_terms_lookup) STRAIGHT_JOIN semantic_lexical_chunks c ON c.index_version = t.index_version AND c.target = t.target AND c.chunk_id = t.chunk_id STRAIGHT_JOIN semantic_lexical_term_stats stats ON stats.index_version = t.index_version AND stats.term = t.term STRAIGHT_JOIN semantic_lexical_index_state state ON state.index_version = t.index_version WHERE t.index_version = (
) AND c.build_status = 'READY' AND t.term IN
#{term}
AND t.target IN
#{target}
GROUP BY t.target, t.chunk_id, c.document_id, t.term, stats.document_frequency, state.active_chunk_count, state.average_weighted_length, c.weighted_length ORDER BY t.target, t.chunk_id, t.term

mapper.insert:
INSERT INTO semantic_lexical_index_state (
  index_version, tokenizer_version, active_chunk_count, average_weighted_length,
  content_fingerprint, status, completed_at
) VALUES (
  #{state.indexVersion}, #{state.tokenizerVersion}, #{state.activeChunkCount},
  #{state.averageWeightedLength}, #{state.contentFingerprint}, #{state.status}, #{state.completedAt}
)
